const cfg = $input.first().json;
const op = cfg.operation;
let path;
let body;
if (op === 'search') {
  path = 'search';
  body = { query: cfg.query || '', ...(cfg.kind ? { kind: cfg.kind } : {}) };
} else if (op === 'inspect') {
  if (!cfg.reference) throw new Error('Copy a reference from Search first.');
  path = 'inspect';
  body = { reference: cfg.reference };
} else if (op === 'start') {
  if (!cfg.reference || !cfg.input || typeof cfg.input !== 'object' || Array.isArray(cfg.input)) throw new Error('Provide an inspected reference and input object.');
  path = 'run';
  body = { reference: cfg.reference, operation: 'start', input: cfg.input, view: cfg.view || 'preview' };
} else if (op === 'status') {
  if (!cfg.reference || !cfg.task_id) throw new Error('Reference and task_id are required.');
  path = 'run';
  body = { reference: cfg.reference, operation: 'status', task_id: cfg.task_id, view: cfg.view || 'preview' };
} else if (op === 'result') {
  if (!cfg.reference || !cfg.request_id) throw new Error('Reference and request_id are required.');
  path = 'run';
  body = { reference: cfg.reference, operation: 'result', request_id: cfg.request_id, view: cfg.view || 'preview' };
} else {
  throw new Error('Operation must be search, inspect, start, status, or result.');
}
return [{ json: { url: `https://api.beatapi.io/v1/capabilities/${path}`, body } }];
